def is_safe(board, row, col, n):
    for i in range(row):
        if board[i] == col or board[i] - i == col - row or board[i] + i == col + row:
            return False
    return True

def solve_nqueens(n, fixed):
    board = [-1] * n
    for row, col in fixed.items():
        board[row] = col
        # Check if fixed positions conflict with each other
        for prev_row in range(row):
            if board[prev_row] != -1:
                prev_col = board[prev_row]
                if prev_col == col or prev_col - prev_row == col - row or prev_col + prev_row == col + row:
                    return None  # Conflict in fixed

    def backtrack(row):
        if row == n:
            return True
        if board[row] != -1:
            return backtrack(row + 1)
        for col in range(n):
            if is_safe(board, row, col, n):
                board[row] = col
                if backtrack(row + 1):
                    return True
                board[row] = -1
        return False

    if backtrack(0):
        return board
    return None

fixed = {4: 4, 6: 1}
solution = solve_nqueens(14, fixed)
print(solution)

from pysat.solvers import Glucose3
import sys

def nqueens_sat(n, fixed):
    # Variables: q_r_c means queen in row r col c, var = r*n + c +1
    def var(r, c):
        return r * n + c + 1

    solver = Glucose3()

    # Exactly one queen per row
    for r in range(n):
        solver.add_clause([var(r, c) for c in range(n)])
        for c1 in range(n):
            for c2 in range(c1+1, n):
                solver.add_clause([-var(r, c1), -var(r, c2)])

    # Exactly one queen per column
    for c in range(n):
        solver.add_clause([var(r, c) for r in range(n)])
        for r1 in range(n):
            for r2 in range(r1+1, n):
                solver.add_clause([-var(r1, c), -var(r2, c)])

    # No two on same diagonal
    for r1 in range(n):
        for c1 in range(n):
            for r2 in range(r1+1, n):
                c2 = c1 + (r2 - r1)
                if c2 < n:
                    solver.add_clause([-var(r1, c1), -var(r2, c2)])
                c2 = c1 - (r2 - r1)
                if c2 >= 0:
                    solver.add_clause([-var(r1, c1), -var(r2, c2)])

    # Fixed positions
    for r, c in fixed.items():
        solver.add_clause([var(r, c)])

    if solver.solve():
        model = solver.get_model()
        solution = [-1] * n
        for r in range(n):
            for c in range(n):
                if model[var(r, c)-1] > 0:
                    solution[r] = c
                    break
        return solution
    else:
        return None

fixed = {4:4, 6:1}
sol = nqueens_sat(14, fixed)
print(sol)
